package ru.elytrix.duelsbridge; class Duels { static Object call(Object obj,String name,Object... args){ if(obj==null)return null;try{for(var m:obj.getClass().getMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){m.setAccessible(true);return m.invoke(obj,args);}}catch(ReflectiveOperationException ex){throw new RuntimeException(ex);}return null;} }
